def is_square(*args, **kwargs):
    if len(args) == 0:
        return False
    n = args[0]
    if not isinstance(n, int):
        return False
    if n < 0:
        return False
    if n == 0 or n == 1:
        return True
    left = 1
    right = n // 2 + 1
    while left <= right:
        mid = (left + right) // 2
        sq = mid * mid
        if sq == n:
            return True
        elif sq < n:
            left = mid + 1
        else:
            right = mid - 1
    return False
